#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minTrioDegree(int n, vector<vector<int>>& edges) {
        vector<vector<bool>> adj(n + 1, vector<bool>(n + 1, false));
        vector<int> degree(n + 1, 0);
        for (const auto& e : edges) {
            adj[e[0]][e[1]] = true;
            adj[e[1]][e[0]] = true;
            degree[e[0]]++;
            degree[e[1]]++;
        }

        int ans = 1e9;
        for (int u = 1; u <= n; ++u) {
            for (int v = u + 1; v <= n; ++v) {
                if (adj[u][v]) {
                    for (int w = v + 1; w <= n; ++w) {
                        if (adj[u][w] && adj[v][w]) {
                            ans = min(ans, degree[u] + degree[v] + degree[w] - 6);
                        }
                    }
                }
            }
        }
        return (ans == 1e9) ? -1 : ans;
    }
};

class Solution {
    public int minTrioDegree(int n, int[][] edges) {
        boolean[][] adj = new boolean[n + 1][n + 1];
        int[] degree = new int[n + 1];
        for (int[] e : edges) {
            adj[e[0]][e[1]] = true;
            adj[e[1]][e[0]] = true;
            degree[e[0]]++;
            degree[e[1]]++;
        }

        int ans = Integer.MAX_VALUE;
        for (int u = 1; u <= n; ++u) {
            for (int v = u + 1; v <= n; ++v) {
                if (adj[u][v]) {
                    for (int w = v + 1; w <= n; ++w) {
                        if (adj[u][w] && adj[v][w]) {
                            ans = Math.min(ans, degree[u] + degree[v] + degree[w] - 6);
                        }
                    }
                }
            }
        }
        return (ans == Integer.MAX_VALUE) ? -1 : ans;
    }
}

