var minTrioDegree = function(n, edges) {
    const adj = Array.from({ length: n + 1 }, () => Array(n + 1).fill(false));
    const degree = Array(n + 1).fill(0);
    for (const [u, v] of edges) {
        adj[u][v] = true;
        adj[v][u] = true;
        degree[u]++;
        degree[v]++;
    }

    let ans = Infinity;
    for (let u = 1; u <= n; ++u) {
        for (let v = u + 1; v <= n; ++v) {
            if (adj[u][v]) {
                for (let w = v + 1; w <= n; ++w) {
                    if (adj[u][w] && adj[v][w]) {
                        ans = Math.min(ans, degree[u] + degree[v] + degree[w] - 6);
                    }
                }
            }
        }
    }
    return ans === Infinity ? -1 : ans;
};
